import pandas as pd, numpy as np
df = pd.read_csv('data/2026_MCM_Problem_C_Data.csv', encoding='utf-8-sig')
# Check the 6.6666 pattern: where do x.3333/x.6666 appear (avg over 3 judges after 2 dances?)
ssum = {}
for s in range(1,35):
    ds = df[df.season==s]
    for w in range(1,12):
        vals = ds[[f'week{w}_judge{j}_score' for j in [1,2,3,4]]].values.flatten()
        vals = vals[~pd.isna(vals) & (vals>0)]
        if len(vals):
            frac = sorted(set(np.round(vals*4 % 4, 2)))
            ssum[(s,w)] = (len(vals), frac)
# find weeks with non-multiples of 0.5
odd = {k:v for k,v in ssum.items() if any(f in {1.0,2.0,3.0} for f in v[1])}
print('weeks containing avg-style scores (x.25/x.33/x.66 style):')
for k,v in list(odd.items())[:30]: print(k, v[0], v[1])
